    _get_ptx_module().function("matmul_tiled")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M = int(A.shape[0])
        K = int(A.shape[1])
        N = int(B.shape[1])

        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y
        split_k = min(32, max(1, (K + 4095) // 4096))
        if split_k > 1:
            C = torch.zeros((M, N), device=A.device, dtype=A.dtype)
        else:
            C = torch.empty((M, N), device=A.device, dtype=A.dtype)
        module.launch(
            "matmul_tiled",
            grid=(grid_x, grid_y, split_k),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C
